/* 실행 시작 추가 */
INSERT INTO BTCH_EXCN_HSTRY (BTCH_SE_CD
                           , EXCN_SE_CD
                           , EXCN_RSLT_CD
                           , MBR_SN
                           , EXCN_BGNG_DT)
VALUES (#{btchSeCd}
      , #{excnSeCd}
      , #{excnRsltCd}
      , #{mbrSn}
      , NOW())

