/* 실행 결과 수정 */
UPDATE BTCH_EXCN_HSTRY
   SET EXCN_RSLT_CD = #{excnRsltCd}
     , EXCN_END_DT = NOW()
     , PRCS_CNT = #{prcsCnt}
     , FAIL_RSN = #{failRsn}
     , MDFCN_DT = NOW()
 WHERE BTCH_EXCN_HSTRY_SN = #{btchExcnHstrySn}

/* 끝나지 못한 실행을 실패로 수정 */
UPDATE BTCH_EXCN_HSTRY
   SET EXCN_RSLT_CD = #{failCd}
     , EXCN_END_DT = NOW()
     , FAIL_RSN = #{failRsn}
     , MDFCN_DT = NOW()
 WHERE EXCN_RSLT_CD = #{runningCd}
